def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid low to conserve budget
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Gather yesterday's bids from opponents' previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Strategy based on yesterday's highest bid
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If opponents bid high yesterday, they may have low HP now
        # Calculate average of yesterday's bids to find typical pressure
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
        # If my HP is critical, bid aggressively
        if hp <= 2:
            target_bid = max(DAILY_SALARY * 0.9, highest_prev_bid + 1)
        elif hp <= 4:
            # Moderate HP: try to win if affordable
            target_bid = min(highest_prev_bid + 1.5, DAILY_SALARY * 0.8)
        else:
            # High HP: save budget, bid just above average if possible
            target_bid = max(avg_prev_bid + 0.5, DAILY_SALARY * 0.4)
        return min(budget, target_bid)

    # No trace: first day or no bids recorded
    # Use baseline based on HP
    if hp <= 2:
        return min(budget, DAILY_SALARY * 0.9)
    elif hp <= 4:
        return min(budget, DAILY_SALARY * 0.6)
    else:
        return min(budget, DAILY_SALARY * 0.45)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # Base urgency from our own state
    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    urgency = 0.0
    if hp <= 2:
        urgency += 0.35
    elif hp <= 4:
        urgency += 0.2
    if no_water_days >= 2:
        urgency += 0.25
    elif no_water_days == 1:
        urgency += 0.12

    # Read yesterday bids from traces for immediate reaction
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Determine target aggressiveness based on their yesterday spend
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If they were very aggressive, we increase but not fully match unless our hp is critical
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            base = DAILY_SALARY * (0.35 if hp > 3 else 0.75)
        # If they were moderate, bid slightly above their likely clearing level
        elif highest_prev_bid >= DAILY_SALARY * 0.55:
            base = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.45)
        else:
            # They were conservative; try to secure water with a mid bid
            base = max(DAILY_SALARY * 0.5, highest_prev_bid + 2.0)
    else:
        # No trace info: conservative early, more urgent later
        base = DAILY_SALARY * (0.45 + 0.05 * min(int(day), 10))

    # Adjust with urgency
    bid = base * (1.0 + urgency)

    # Supply-aware scaling: when supply is low, increase bids to win allocation
    # (supply is float; use it only for arithmetic, not indexing)
    if supply <= MIN_SUPPLY + 1:
        bid *= 1.15
    elif supply >= MAX_SUPPLY - 1:
        bid *= 0.95

    # Ensure bid is feasible: cannot exceed budget
    if budget <= 0:
        return 0.0

    # Also cap to avoid reckless spending when hp is decent
    hp_safe_cap = DAILY_SALARY * (0.95 if hp <= 2 else 0.7)
    bid = min(bid, hp_safe_cap)
    bid = min(bid, budget)

    # Final sanity: non-negative
    if bid < 0:
        bid = 0.0
    return float(bid)
